def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [i for i in intervals if i[0] < i[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping, add new interval
                merged.append([start, end])

        return merged

    # Merge both a and b to get canonical forms
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    # For each interval in a, subtract all intervals in b
    result = []

    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_current = []

            for c_start, c_end in current:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    next_current.append([c_start, c_end])
                else:
                    # There is overlap, split c
                    if c_start < b_start:
                        next_current.append([c_start, b_start])
                    if c_end > b_end:
                        next_current.append([b_end, c_end])

            current = next_current

        result.extend(current)

    return result

